INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Cursor in einer Datenbank dasselbe wie ein Zeiger in C?', 2, '[{"text": "Nein", "correct": true, "because": "Cursor navigiert Datensätze, Zeiger Speicher"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Kontexte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Zweck verfolge ich mit einem Cursor?', 3, '[{"text": "Datensätze durchlaufen", "correct": true, "because": "Zeilenweise Verarbeitung"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Kein Sicherheitsfokus"}, {"text": "Tabellen erstellen", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat ein Cursor?', 5, '[{"text": "Navigierbar", "correct": true, "because": "Bewegt sich durch Ergebnisse"}, {"text": "Aktualisierbar", "correct": true, "because": "Kann Daten ändern"}, {"text": "Permanent gespeichert", "correct": false, "because": "Temporär"}, {"text": "Grafisch", "correct": false, "because": "Kein UI-Element"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Cursor verarbeitet Ergebnisse zeilenweise. b) Er ersetzt SQL-Abfragen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ergänzt Abfragen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Arbeit mit einem Cursor?', 4, '[{"text": "Leistungsaufwand", "correct": false, "because": "Kann Performance beeinflussen"}, {"text": "Schließung", "correct": false, "because": "Ressourcen freigeben"}, {"text": "Farbeinstellung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Cursor immer scrollt?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bei scrollbaren Cursorn"}, {"text": "Ja", "correct": false, "because": "Typabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Typ nutze ich für einfache Lesezugriffe?', 3, '[{"text": "Forward-Only", "correct": true, "because": "Effizient für Einweg"}, {"text": "Dynamic", "correct": false, "because": "Zu komplex"}, {"text": "Static", "correct": false, "because": "Kopie, nicht live"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Cursor?', 5, '[{"text": "Zeilenweise Steuerung", "correct": true, "because": "Präzise Verarbeitung"}, {"text": "Flexibilität", "correct": true, "because": "Anpassbare Navigation"}, {"text": "Dauerhafte Speicherung", "correct": false, "because": "Temporär"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Kann langsamer sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Cursor sind für komplexe Abfragen. b) Sie sind immer schneller als Abfragen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Oft langsamer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Cursor?', 4, '[{"text": "Abfrage", "correct": false, "because": "Grundlage des Cursors"}, {"text": "Datenbankverbindung", "correct": false, "because": "Zugriff nötig"}, {"text": "Grafiktreiber", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Cursor immer editierbar?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig vom Typ"}, {"text": "Ja", "correct": false, "because": "Nicht alle sind updatable"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Typen gibt es?', 4, '[{"text": "Static", "correct": true, "because": "Snapshot der Daten"}, {"text": "Keyset", "correct": true, "because": "Dynamisch mit Schlüsseln"}, {"text": "Permanent", "correct": false, "because": "Gibt es nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Cursor nur für kleine Datenmengen sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für große Sets nutzbar"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Nutzung?', 3, '[{"text": "Performance", "correct": true, "because": "Kann Ressourcen belasten"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Effizienz zählt"}, {"text": "Minimale Größe", "correct": false, "because": "Nicht entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Cursor sind temporär. b) Sie ersetzen Joins.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Joins bleiben nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Operationen unterstützt ein Cursor?', 5, '[{"text": "Lesen", "correct": true, "because": "Durchläuft Daten"}, {"text": "Aktualisieren", "correct": true, "because": "Bei bestimmten Typen"}, {"text": "Tabellen erstellen", "correct": false, "because": "Nicht seine Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Verwendung unwichtig?', 3, '[{"text": "Schließung", "correct": false, "because": "Ressourcen freigeben"}, {"text": "Typwahl", "correct": false, "because": "Beeinflusst Funktion"}, {"text": "Bildschirmhelligkeit", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Nutzt ein Cursor immer Transaktionen?', 3, '[{"text": "Nein", "correct": true, "because": "Kontextabhängig"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Cursor für einfache Abfragen nötig sind?', 2, '[{"text": "Nein", "correct": true, "because": "Für komplexe Fälle"}, {"text": "Ja", "correct": false, "because": "Oft überflüssig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Datenbank dabei?', 4, '[{"text": "Liefert Ergebnisse", "correct": true, "because": "Grundlage des Cursors"}, {"text": "Zeichnet Grafiken", "correct": false, "because": "Kein Zusammenhang"}, {"text": "Erhöht Bandbreite", "correct": false, "because": "Irrelevant"}]');
